test('water-contact admission retries on demand and revalidates structural changes',async()=>{
 let clock=0,calls=0;const pending=[],errors=[],worker={id:'w',profile:'olderMale',status:'walking',x:0,z:0,walkPhase:0},state={time:30,elapsed:0,spells:[],events:[],structures:[],plants:[],tasks:[],workers:[worker],raid:null},scene=new THREE.Scene(),turn=()=>new Promise(resolve=>setImmediate(resolve)),admission={structuralRevision:0,prepare(){calls++;if(calls===1)return Promise.reject(Error('transient'));return new Promise(resolve=>pending.push(resolve));}},vfx=createWebGpuAgricultureVfx({scene,state,residency:{get:()=>({})},includeLocomotion:true,locomotionWater:()=>({available:true,inside:true,level:2}),pipelineAdmission:admission,now:()=>clock,onError:error=>errors.push(error.message)}),camera=new THREE.PerspectiveCamera();
 try{vfx.sync();worker.x=.1;worker.walkPhase=4;state.elapsed=.1;vfx.sync();await turn();const mesh=scene.getObjectByName('canyon-step-ripples');assert.ok(mesh);assert.equal(mesh.visible,false);assert.equal(calls,1);assert.deepEqual(errors,['transient']);vfx.prepare(camera);await turn();assert.equal(calls,1);clock=1000;vfx.prepare(camera);await turn();assert.equal(calls,2);pending.shift()();await turn();assert.equal(mesh.visible,true);admission.structuralRevision++;vfx.prepare(camera);assert.equal(mesh.visible,false);await turn();assert.equal(calls,3);pending.shift()();await turn();assert.equal(mesh.visible,true);assert.equal(vfx.status().locomotion.ripplesReady,true);}finally{vfx.dispose();}
});

